#!/usr/bin/env node
// Renders who-we-are/index.html from src/data/who-we-are.json (GENERATED by ~/bin/who-we-are.mjs
// from the fleet registry; re-run that, then this). The page reuses the MCP help page's shell and
// prose styles, so there is no new CSS. Run: node tools/render-who-we-are.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
const wwa = JSON.parse(readFileSync('src/data/who-we-are.json', 'utf8'));
const tpl = readFileSync('mcp-server/index.html', 'utf8');
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const origin = 'https://jarvising.com', url = `${origin}/who-we-are/`;
const title = `Who we are: ${wwa.org.name} · Jarvising`;
const desc = `Jarvising is run by ${wwa.org.name}, a London software studio. What the studio does, and the ${wwa.count} projects it runs.`;
const projects = wwa.sections.flatMap(s => s.projects);
const graph = {
  '@context': 'https://schema.org',
  '@graph': [
    { '@type': 'Organization', '@id': `${origin}/#org`, name: 'Jarvising', url: `${origin}/`, parentOrganization: wwa.parentOrganization },
    { '@type': 'AboutPage', '@id': `${url}#page`, url, name: `Who we are: ${wwa.org.name}`, about: { '@id': wwa.org.id },
      mainEntity: { '@type': 'ItemList', name: `Projects by ${wwa.org.name}`, numberOfItems: wwa.count,
        itemListElement: projects.map((p, i) => ({ '@type': 'ListItem', position: i + 1, name: p.name, url: p.url })) } },
  ],
};
const item = p => `<li>${p.self ? `<strong>${esc(p.name)}</strong> (this site)` : `<a href="${esc(p.url)}"><strong>${esc(p.name)}</strong></a>`}: ${esc(p.description)}</li>`;
const prose = [
  ...wwa.intro.map(p => `<p>${esc(p)}</p>`),
  `<p>The studio's own site is <a href="${esc(wwa.org.url)}">${esc(wwa.org.url.replace('https://', ''))}</a>.</p>`,
  ...wwa.sections.map(s => `<h2>${esc(s.title)}</h2>\n<ul>${s.projects.map(item).join('')}</ul>`),
  `<p>${esc(wwa.footnote)}</p>`,
].join('\n');
const sub = (s, re, to) => { if (!re.test(s)) throw new Error('template marker missing: ' + re); return s.replace(re, () => to); };
let h = tpl;
h = sub(h, /<title>.*<\/title>/, `<title>${esc(title)}</title>`);
h = sub(h, /<meta name="description" content="[^"]*">/, `<meta name="description" content="${esc(desc)}">`);
h = sub(h, /<link rel="canonical" href="[^"]*">/, `<link rel="canonical" href="${url}">`);
h = sub(h, /<meta property="og:title" content="[^"]*">/, `<meta property="og:title" content="${esc(title)}">`);
h = sub(h, /<meta property="og:description" content="[^"]*">/, `<meta property="og:description" content="${esc(desc)}">`);
h = sub(h, /<meta property="og:url" content="[^"]*">/, `<meta property="og:url" content="${url}">`);
h = sub(h, /<\/head>/, `<script type="application/ld+json">${JSON.stringify(graph)}</script>\n</head>`);
h = sub(h, /<\/b><\/a> · MCP server<\/span>/, '</b></a> · who we are</span>');
h = sub(h, /<h1 class="headword fade fade-2">[^<]*<\/h1>/, `<h1 class="headword fade fade-2">${esc(wwa.org.name)}</h1>`);
h = sub(h, /<div class="prose fade fade-3">[\s\S]*?\n    <\/div>\n  <\/main>/, `<div class="prose fade fade-3">\n${prose}\n    </div>\n  </main>`);
mkdirSync('who-we-are', { recursive: true });
writeFileSync('who-we-are/index.html', h);
console.log('wrote who-we-are/index.html', projects.length, 'projects');
